function renderInline(text: string): ReactNode[] {
  return text
    .split(/(<strong>[\s\S]*?<\/strong>|<a\s[^>]*>[\s\S]*?<\/a>|<br\s*\/?>)/g)
    .filter(Boolean)
    .map((part, i) => {
      if (part.startsWith("<strong>")) return <strong key={i}>{part.slice(8, -9)}</strong>;
      const link = part.match(/^<a\s+href="([^"]*)"[^>]*>([\s\S]*?)<\/a>$/);
      if (link) return <a key={i} href={link[1]} target="_blank" rel="noopener noreferrer">{link[2]}</a>;
      if (part.startsWith("<br")) return <br key={i} />;
      return <Fragment key={i}>{part}</Fragment>;
    });
}

function renderBlock(block: Block, index: number) {
  if (block.kind === "list") {
    return (
      <ul key={index}>
        {block.items.map((item, i) => (
          <li key={i}>{renderInline(item)}</li>
        ))}
      </ul>
    );
  }
  if (block.kind === "sub") return <h3 key={index}>{block.text}</h3>;
  return <p key={index}>{renderInline(block.text)}</p>;
}

export function LegalDoc({ page }: { page: LegalPage }) {
  const { locale } = useLocale();
  const doc = DOCS[page][locale] ?? DOCS[page].it;
  return (
    <>
      <section className="legal-hero">
        <p className="eyebrow">{doc.eyebrow}</p>
        <h1>{doc.title}</h1>
      </section>
      <article className="legal-doc">
        {doc.intro.map(renderBlock)}
        {doc.sections.map((section, i) => (
          <section className="legal-section" key={i}>
            <h2>{section.title}</h2>
            {section.blocks.map(renderBlock)}
          </section>
        ))}
      </article>
    </>
  );
}
